-- mod-challenges: Boaring Adventure's boar herds (world database).
-- Written by tools/build_herds.py; edit the bands there and run it again rather than editing this file.
-- One creature per level band (9507000-9507049), copied from a stock boar of about that level (its AI,
-- faction and loot), and small herds in the band's zone (spawn guids 9507100-9508999). They stand in phase
-- 67108864 (bit 26), which only Boaring Adventure characters are in, through the server-side aura
-- spell 90700. Nobody else sees them. Idempotent. Undo with data/sql/uninstall/mod_challenges_uninstall_world.sql.

DELETE FROM `spell_dbc` WHERE `ID` = 90700;

DELETE FROM `creature` WHERE `guid` BETWEEN 9507100 AND 9508999;
DELETE FROM `smart_scripts` WHERE `entryorguid` BETWEEN 9507000 AND 9507099 AND `source_type` = 0;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 9507000 AND 9507099;
DELETE FROM `creature_template_movement` WHERE `CreatureId` BETWEEN 9507000 AND 9507099;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 9507000 AND 9507099;

-- Copies of the stock boars, without naming their columns.
DROP TEMPORARY TABLE IF EXISTS `mod_challenges_boar`;
CREATE TEMPORARY TABLE `mod_challenges_boar` LIKE `creature_template`;
